# -*- coding: utf-8 -*-
"""Заключение и список источников."""

from sources import SOURCES, cite


def ending():
    blocks = []
    P = lambda text: blocks.append(("p", text))
    blocks.append(("h1", "ЗАКЛЮЧЕНИЕ"))
    P("Работа разбирала деятельность специалиста по социальной работе с детьми-сиротами и детьми, оставшимися без попечения родителей. Нужно было понять, кто этот ребенок для социальной работы, что обязан уметь специалист, как устроено жизнеустройство в стране и в Орловской области и каким порядком вести один случай. Отдельного опроса сотрудников не проводилось. Опорой были законы, исследования и официальные сведения. Поэтому выводы не шире этой опоры.")
    P("Ребенок данной категории имеет право на семью, и закон ставит семейное устройство выше жизни в организации. Биологическое сиротство и социальное сиротство требуют разной человеческой работы, хотя гарантии у них общие. В первом случае рядом горе и поиск новых взрослых. Во втором чаще всего живы родители, которые не исполняли долг, и у ребенка уже есть опыт пренебрежения или жестокости. Исследователи сходятся в том, что длительная жизнь в большой группе без постоянного близкого взрослого бьет по общению, по образу будущего и по умению отвечать за себя. Интеллект при этом может быть сохранен. Среда лечится средой: маленькая группа, свой воспитатель, личные вещи, понятный план, а не только режим питания.")
    P("Портрет специалиста складывается из подготовки, знания права, умения слышать ребенка и из устойчивости. Его функции идут по цепочке случая. Он выясняет, чего не хватает, ставит цель, которую можно проверить, собирает врача, педагога, психолога и опеку, защищает уже существующее право и смотрит, сдвинулось ли дело. Профилактика начинается раньше учреждения: в кризисной помощи матери, в сопровождении неблагополучной семьи, в разговоре с молодежью о заботе. Организация по постановлению Правительства от 24 мая 2014 года номер 481 сама является частью этой профилактики, потому что должна сокращать срок пребывания и готовить либо возврат, либо новую семью, либо самостоятельную жизнь.")
    P("Официальный счет второй главы не нужно переписывать заново. Достаточно удержать соотношение: около 91 процента детей данной категории живут в семьях, около 9 процентов — в организациях, и оба ряда за пять лет снизились. Нехватки кадров опеки, орловской жилищной очереди и 164 детей в пяти центрах довольно, чтобы понять предел нагрузки. Семейное устройство в области идет, и это не отменяет ни очередь, ни детей, которые все еще живут в центрах.")
    P("Дорожная карта предлагает специалисту восемь шагов от первого месяца до жилья и выпуска. Учебный план воспитанника Н. показывает, как шаги выглядят, когда у подростка есть сестра, живая мать без прав и еще нет записи в жилищном списке. Польза плана не в толщине, а в том, что через полгода каждая строка либо подтверждается, либо честно переписывается. Мнение ребенка, запрет разлучать братьев и сестер без основания и фамилия куратора — не пожелания. Они уже есть в законе. Работа только собирает их в один порядок, которым можно пользоваться в орловском центре, не дожидаясь нового штатного расписания.")
    P("Практическое значение поэтому узкое и прикладное. Администрация организации может сверить свой бланк плана с тремя частями и с таблицей шагов и убрать формулировки, которые нельзя проверить. Опека может не утверждать план без фамилии куратора и без записи о мнении ребенка. Сам специалист получает напоминание, что жилищный учет начинается с четырнадцати лет, а не в день совершеннолетия, и что гостевой режим честнее, чем быстрая передача ради отчета. Поддержки работников это тоже касается. Постановление номер 481 требует ее прямо, а выгорание при дефиците кадров иначе съест и самый точный бланк.")
    P("Ограничение работы честное. Она не измеряла, сколько действующих орловских планов уже написаны пустыми фразами, и не опрашивала кураторов о усталости. Такие замеры были бы следующим шагом, уже на базе практики, с согласием учреждения и без выноса чужих судеб в текст. Пока же достаточно документального разбора и проекта, который можно приложить к действующему порядку. " + cite("conv", "Во всех действиях в отношении детей первоочередное внимание уделяется наилучшему обеспечению интересов ребенка.") + " Для специалиста этот интерес каждый раз имеет имя, срок и следующий шаг, а не только правильную ссылку на кодекс.")

    blocks.append(("break",))
    blocks.append(("h1", "СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ"))
    for i, (key, text) in enumerate(SOURCES, start=1):
        blocks.append(("bib", i, text))
    return blocks
